548	/// Batched hidden states: seq_len vectors of dim hidden_dim, stored contiguously.
549	/// Memory layout: [hidden_dim * seq_len] elements, token i at offset i * hidden_dim.
550	/// cuBLAS interprets as [hidden_dim, seq_len] column-major.
551	pub struct HiddenStates {
552	    pub data: CudaSlice<bf16>,
553	    pub hidden_dim: usize,
554	    pub seq_len: usize,
555	}
556	
557	impl HiddenStates {
558	    /// The band `[col, col + width)` of every row.
559	    pub fn columns(&self, col: usize, width: usize) -> Columns<'_> {
560	        Columns {
561	            states: self,
562	            col,
563	            width,
564	        }
565	    }
566	
567	    pub fn as_ref(&self) -> HiddenStatesRef<'_> {
568	        HiddenStatesRef {
569	            data: &self.data,
570	            hidden_dim: self.hidden_dim,
571	            seq_len: self.seq_len,
572	        }
573	    }
574	
575	    /// Logical extent `hidden_dim * seq_len`, checked to fit the backing
576	    /// allocation (`>=`, not `==`: buffers allocate at a max and rewrite
577	    /// `seq_len` to the active size per step). Fields are public, so a safe
578	    /// caller can shape a logical size past the backing; launch wrappers
579	    /// call this to reject that before it reaches a kernel.
580	    pub(crate) fn checked_extent(&self, what: &str) -> Result<usize> {
581	        let extent = self
582	            .hidden_dim
583	            .checked_mul(self.seq_len)
584	            .ok_or_else(|| anyhow!("{what} logical extent overflow"))?;
585	        if self.data.len() < extent {
586	            return Err(anyhow!(
587	                "{what} backing len {} < hidden_dim {} * seq_len {}",
588	                self.data.len(),
589	                self.hidden_dim,
590	                self.seq_len
591	            ));
592	        }
593	        Ok(extent)
594	    }
595	
596	    /// Create zeroed batch
597	    pub fn zeros(ctx: &DeviceContext, hidden_dim: usize, seq_len: usize) -> Result<Self> {
598	        let data: CudaSlice<bf16> = ctx
599	            .stream
600	            .alloc_zeros(hidden_dim * seq_len)
601	            .map_err(|e| anyhow!("Alloc failed: {}", e))?;
602	        Ok(Self {
603	            data,
604	            hidden_dim,
605	            seq_len,
606	        })
607	    }
608	
609	    /// Create from host data: `hidden_dim * seq_len` bf16, token `i` at `i * hidden_dim`.
610	    pub fn from_host(
611	        ctx: &DeviceContext,
612	        data: &[bf16],
613	        hidden_dim: usize,
614	        seq_len: usize,
615	    ) -> Result<Self> {
616	        assert_eq!(data.len(), hidden_dim * seq_len);
617	        let gpu_data = ctx
618	            .stream
619	            .clone_htod(data)
620	            .map_err(|e| anyhow!("H2D copy failed: {}", e))?;
621	        Ok(Self {
622	            data: gpu_data,
623	            hidden_dim,
624	            seq_len,
625	        })
626	    }
627	
628	    /// Copy to host as f32. bf16 → f32 is lossless, so f32 equality is bitwise.
629	    pub fn to_host(&self, ctx: &DeviceContext) -> Result<Vec<f32>> {
630	        let host = ctx
631	            .stream
632	            .clone_dtoh(&self.data)
633	            .map_err(|e| anyhow!("D2H copy failed: {}", e))?;
634	        ctx.sync()?;
635	        Ok(host.iter().map(|x| x.to_f32()).collect())
636	    }
637	}
638	
639	// ── Typed tensor layer ───────────────────────────────────────────────
640	//
641	// `GpuTensor<DIM>` encodes the hidden dimension in the type. The seq_len
642	// (batch) axis stays runtime because it changes per step. Weight matrices
643	// carry both dimensions: `GpuWeight<OUT, IN>`.
644	//
645	// These are additive — existing `HiddenStates`/`DeviceMatrix` stay untouched.
646	// Model crates migrate one at a time.
647	
648	/// Batched bf16 activation tensor with compile-time hidden dimension.
649	///
650	/// Memory layout: `[DIM * seq_len]` contiguous bf16, token `i` at `i * DIM`.
651	/// cuBLAS sees `[DIM, seq_len]` column-major.
652	pub struct GpuTensor<const DIM: usize> {
653	    pub data: CudaSlice<bf16>,
654	    pub seq_len: usize,
655	}
656	
657	impl<const DIM: usize> GpuTensor<DIM> {
658	    pub fn zeros(ctx: &DeviceContext, seq_len: usize) -> Result<Self> {
659	        let data: CudaSlice<bf16> = ctx
660	            .stream
661	            .alloc_zeros(DIM * seq_len)
662	            .map_err(|e| anyhow!("GpuTensor<{}>::zeros alloc failed: {}", DIM, e))?;
663	        Ok(Self { data, seq_len })
664	    }
665	
666	    pub fn from_device_matrix_rows(m: DeviceMatrix) -> Result<Self> {
667	        anyhow::ensure!(
668	            m.cols == DIM,
669	            "GpuTensor<{}>::from_device_matrix_rows col mismatch: got {}",
670	            DIM,
671	            m.cols,
672	        );
673	        Ok(Self {
674	            data: m.data,
675	            seq_len: m.rows,
676	        })
677	    }
678	}
679	
680	/// bf16 weight matrix with compile-time dimensions: `[OUT, IN]` row-major.
681	pub struct GpuWeight<const OUT: usize, const IN: usize> {
682	    pub(crate) data: CudaSlice<bf16>,
683	}
684	
685	impl<const OUT: usize, const IN: usize> GpuWeight<OUT, IN> {
686	    pub fn from_device_matrix(m: DeviceMatrix) -> Result<Self> {
687	        anyhow::ensure!(
688	            m.rows == OUT && m.cols == IN,
689	            "GpuWeight<{}, {}>::from_device_matrix shape mismatch: got [{}, {}]",
690	            OUT,
691	            IN,
692	            m.rows,
693	            m.cols,
694	        );
695	        Ok(Self { data: m.data })
696	    }
697	}
698	
699	/// bf16 RMSNorm weight vector with compile-time dimension.
700	pub struct NormWeight<const DIM: usize> {
701	    pub data: CudaSlice<bf16>,
702	}
703	
704	impl<const DIM: usize> NormWeight<DIM> {
705	    pub fn from_device_vec(v: DeviceVec) -> Result<Self> {
706	        anyhow::ensure!(
707	            v.len == DIM,
708	            "NormWeight<{}>::from_device_vec len mismatch: got {}",
709	            DIM,
710	            v.len,
711	        );
712	        Ok(Self { data: v.data })
713	    }
714	}
715	
716	/// f32 raw buffer with compile-time element count per batch entry.
717	pub struct GpuRawSlice<const ELEMS: usize> {
718	    pub data: CudaSlice<f32>,
719	    pub batch_size: usize,
720	}
721	
722	impl<const ELEMS: usize> GpuRawSlice<ELEMS> {
723	    pub fn zeros(ctx: &DeviceContext, batch_size: usize) -> Result<Self> {
724	        let data: CudaSlice<f32> = ctx
725	            .stream
726	            .alloc_zeros(ELEMS * batch_size)
727	            .map_err(|e| anyhow!("GpuRawSlice<{}>::zeros alloc failed: {}", ELEMS, e))?;
728	        Ok(Self { data, batch_size })
729	    }
730	}
731	
732	/// i32 raw buffer with compile-time element count per batch entry.
733	pub struct GpuRawSliceI32<const ELEMS: usize> {
734	    pub data: CudaSlice<i32>,
735	    pub batch_size: usize,
736	}
737	
738	impl<const ELEMS: usize> GpuRawSliceI32<ELEMS> {
739	    pub fn zeros(ctx: &DeviceContext, batch_size: usize) -> Result<Self> {
740	        let data: CudaSlice<i32> = ctx
741	            .stream
742	            .alloc_zeros(ELEMS * batch_size)
743	            .map_err(|e| anyhow!("GpuRawSliceI32<{}>::zeros alloc failed: {}", ELEMS, e))?;
744	        Ok(Self { data, batch_size })
745	    }
746	}
747	
748	/// Non-owning reference to `HiddenStates`-shaped data (bridge to untyped ops).
749	#[derive(Clone, Copy)]
750	pub struct HiddenStatesRef<'a> {
751	    pub data: &'a CudaSlice<bf16>,
752	    pub hidden_dim: usize,
753	    pub seq_len: usize,
754	}
755	
756	/// The columns `[col, col + width)` of every row of a `HiddenStates`: the
757	/// band one projection occupies when a row holds several, read at the row's
758	/// full stride. A whole tensor is its own band from column 0.
759	#[derive(Clone, Copy)]
760	pub struct Columns<'a> {
761	    pub states: &'a HiddenStates,
762	    pub col: usize,
763	    pub width: usize,
764	}
765	
766	impl<'a> From<&'a HiddenStates> for Columns<'a> {
767	    fn from(states: &'a HiddenStates) -> Self {
768	        Self {
769	            states,
770	            col: 0,
771	            width: states.hidden_dim,
772	        }
773	    }
774	}
775	
776	impl Columns<'_> {
777	    /// Panics unless the band lies within the row. `columns` and the public
778	    /// fields accept any band, and a launch that reads `width` columns at the
779	    /// row stride from `col` would otherwise run past the last row's end.
780	    pub fn assert_in_row(&self, what: &str) {
781	        assert!(
782	            self.col
783	                .checked_add(self.width)
784	                .is_some_and(|end| end <= self.states.hidden_dim),
785	            "{what} columns [{}..+{}) exceed the row's {}",
786	            self.col,
787	            self.width,
788	            self.states.hidden_dim
789	        );
790	    }
791	}
792	
793	#[cfg(test)]
794	mod tests {
795	    use super::*;
796	
797	    #[test]
798	    fn stream_override_guard_restores_on_drop() {
799	        let outer = 0x10usize as CUstream;
800	        assert!(!has_stream_override());
801	        assert!(!has_prefill_stream_override());
802	        {
803	            let _outer_guard = unsafe { StreamOverrideGuard::activate_prefill(outer) };
804	            assert!(has_prefill_stream_override());
805	            {
806	                let _inner_guard = unsafe { StreamOverrideGuard::activate(0x20usize as CUstream) };
807	                assert!(!has_prefill_stream_override());
808	            }
809	            assert_eq!(STREAM_OVERRIDE.with(Cell::get), Some(outer));
810	            assert!(has_prefill_stream_override());
811	        }
812	        assert!(!has_stream_override());
813	        assert!(!has_prefill_stream_override());
814	    }
815	
816	    fn copy_matrix_to_host(ctx: &DeviceContext, matrix: &DeviceMatrix) -> Vec<bf16> {
817	        let host = ctx
818	            .stream
819	            .clone_dtoh(&matrix.data)
820	            .expect("D2H copy failed");
821	        ctx.sync().expect("CUDA sync failed");
822	        host
823	    }
824	
825	    #[test]
826	    fn test_device_matrix_from_safetensors_matches_from_host() {
827	        let ctx = DeviceContext::new().expect("Failed to create CUDA context");
828	        let rows = 3;
829	        let cols = 2;
830	        let host = vec![
831	            bf16::from_f32(-8.0),
832	            bf16::from_f32(-0.25),
833	            bf16::from_f32(1.0),
834	            bf16::from_f32(3.5),
835	            bf16::from_f32(9.0),
836	            bf16::from_f32(10.75),
837	        ];
838	        let safetensor_bytes: Vec<u8> = host
839	            .iter()
840	            .flat_map(|v| v.to_bits().to_le_bytes())
841	            .collect();
842	
843	        let from_host =
844	            DeviceMatrix::from_host(&ctx, &host, rows, cols).expect("from_host should succeed");
845	        let from_safetensors = DeviceMatrix::from_safetensors(&ctx, &safetensor_bytes, rows, cols)
846	            .expect("from_safetensors should succeed");
847	
848	        assert_eq!(from_safetensors.rows, from_host.rows);
849	        assert_eq!(from_safetensors.cols, from_host.cols);
850	
851	        let host_out = copy_matrix_to_host(&ctx, &from_host);
852	        let safetensors_out = copy_matrix_to_host(&ctx, &from_safetensors);
853	        assert_eq!(host_out.len(), safetensors_out.len());
854	        for (idx, (a, b)) in host_out.iter().zip(safetensors_out.iter()).enumerate() {
